package company.backend.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Reset another administrator's password.
 *
 * <p>The new secret is generated by the caller and forced to be changed at
 * next sign in. An existing password is never revealed, because the server
 * only ever stores a hash.
 */
public record ResetPasswordRequest(

		@NotBlank(message = "A new password is required")
		@Size(max = 100, message = "Password must be 100 characters or fewer")
		String newPassword) {
}